function bestUpDownUp(nums: number[]): number {
  const n = nums.length;
  let best = -Infinity;
  for (let l = 0; l < n; l++) {
    let phase = 1, steps = 0, sum = nums[l];
    for (let j = l + 1; j < n; j++) {
      const up = nums[j] > nums[j - 1], down = nums[j] < nums[j - 1];
      if (phase === 1) {
        if (up) steps++;
        else if (down && steps > 0) phase = 2;
        else break;
      } else if (phase === 2) {
        if (up) phase = 3;
        else if (!down) break;
      } else if (!up) break;
      sum += nums[j];
      if (phase === 3) best = Math.max(best, sum);
    }
  }
  return best;
}

