function bestUpDownUp(nums: number[]): number {
  let up1 = -Infinity, down = -Infinity, up2 = -Infinity, ans = -Infinity;
  for (let i = 1; i < nums.length; i++) {
    const x = nums[i], prev = nums[i - 1];
    if (x > prev) {
      up2 = Math.max(up2, down) + x; // reads the old down
      up1 = Math.max(up1, prev) + x; // extend, or start fresh at prev
      down = -Infinity;
    } else if (x < prev) {
      down = Math.max(down, up1) + x;
      up1 = up2 = -Infinity;
    } else {
      up1 = down = up2 = -Infinity;
    }
    ans = Math.max(ans, up2);
  }
  return ans;
}

